<?php session_start();if(empty($_SESSION['logged_in'])){header('Location: login.php');exit;}if(!isset($_SESSION['employees']))$_SESSION['employees']=[];$errors=[];$name=$email=$dept='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$dept=$_POST['department']??'';if($name==='')$errors[]='Name is required.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Valid email is required.';if(!in_array($dept,['IT','HR','Finance','Sales'],true))$errors[]='Choose a department.';foreach($_SESSION['employees'] as $x)if(strtolower($x['email'])===strtolower($email))$errors[]='Email already exists.';if(!$errors){$id=1;foreach($_SESSION['employees'] as $x)$id=max($id,$x['id']+1);$_SESSION['employees'][]=['id'=>$id,'name'=>$name,'email'=>$email,'department'=>$dept];$_SESSION['flash']='Employee added successfully.';header('Location: index.php');exit;}}function h($x){return htmlspecialchars((string)$x,ENT_QUOTES,'UTF-8');} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Add Employee</title><link rel="stylesheet" href="assets/style.css"></head><body><main><h1>Add employee</h1><?php foreach($errors as $e)echo '<p class="error">'.h($e).'</p>';?><form method="post"><label>Name<input name="name" value="<?=h($name)?>" required></label><label>Email<input type="email" name="email" value="<?=h($email)?>" required></label><label>Department<select name="department" required><option value="">Choose</option><?php foreach(['IT','HR','Finance','Sales'] as $v)echo '<option '.($dept===$v?'selected':'').'>'.$v.'</option>';?></select></label><button>Save employee</button><a href="index.php">Cancel</a></form></main></body></html>